
import type { Questionnaire } from "../types/questionnaire";

// Load a questionnaire from the PHP API
export async function loadQuestionnaire(
  _filename?: string
): Promise<Questionnaire> {

  // Get questionnaire ID from URL, or use 1001 by default
  const params = new URLSearchParams(window.location.search);

  const questionnaireId =
    params.get("id") || "1001";

  // Validate the questionnaire ID
  if (!/^[0-9]+$/.test(questionnaireId)) {
    throw new Error("Invalid questionnaire ID");
  }

  // Fetch questionnaire generated by PHP from MySQL
  const response = await fetch(
    `/api/questionnaire.php?id=${questionnaireId}`
  );

  // Check whether the API request succeeded
  if (!response.ok) {
    throw new Error("Could not load the questionnaire");
  }

  // Convert JSON response into an object
  const questionnaire = await response.json();

  // Validate the main questionnaire structure
  if (
    !questionnaire ||
    !Array.isArray(questionnaire.pages) ||
    !Array.isArray(questionnaire.categories) ||
    !questionnaire.questions ||
    typeof questionnaire.questions !== "object"
  ) {
    throw new Error("The questionnaire JSON is not valid");
  }

  return questionnaire as Questionnaire;
}
